      "keystrokes": "cat << 'CPP' > main.cpp\n#include <bits/stdc++.h>\nusing namespace std;\n\n// Check if staircase with n stairs is nice using a bitset DP over sums of deltas (k^2-1 for k>=2)\nbool isNiceBitset(int n, long long maxMCap) {\n    long long S = 1LL * n * (n + 1) / 2; // total cells in staircase\n    long long M = S - n; // required sum of deltas (ai^2 - 1) across all ai\n    if (M < 0) return false;\n    if (M == 0) return true; // all squares are 1x1, rest can be 1^2\n\n    // deltas = k^2 - 1 for k >= 2 with delta <= M\n    int maxK = (int)floor(sqrt((long double)M + 1e-12));\n    vector<int> deltas;\n    for (int k = 2; k <= maxK; ++k) {\n        long long d = 1LL * k * k - 1;\n        if (d > M) break;\n        deltas.push_back((int)d);\n    }\n    if (deltas.empty()) return false;\n\n    int W = (M + 64) / 64; // number of 64-bit blocks to cover 0..M\n    vector<unsigned long long> cur(W, 0), next(W, 0);\n    cur[0] = 1ULL; // sum 0 achievable with 0 non-1 squares\n\n    auto bit_test = [&](const vector<unsigned long long>& b, long long pos)->bool {\n        int idx = pos / 64; int off = pos % 64; if (idx >= (int)b.size()) return false; return ((b[idx] >> off) & 1ULL) != 0ULL; };\n\n    // check initial 0 items case: if M == 0 handled above\n    for (int i = 1; i <= n; ++i) {\n        fill(next.begin(), next.end(), 0ULL);\n        for (int d : deltas) {\n            int shift = d;\n            int bShift = shift / 64;\n            int bitShift = shift % 64;\n            for (int idx = 0; idx < W; ++idx) {\n                unsigned long long val = cur[idx];\n                if (!val) continue;\n                int t = idx + bShift;\n                if (t < W) {\n                    next[t] |= (bitShift ? (val << bitShift) : val);\n                    if (bitShift && t + 1 < W) {\n                        next[t+1] |= (unsigned long long)(val >> (64 - bitShift));\n                    }\n                }\n            }\n        }\n        // mask off bits beyond M in the last block\n        int lastBits = (W * 64) - (M + 1);\n        if (lastBits > 0) {\n            unsigned long long mask = ~0ULL >> lastBits; // keep lower (64 - lastBits) bits\n            next[W-1] &= mask;\n        }\n        cur.swap(next);\n        // if achievable with exactly i non-1-squares, we can fill rest with 1x1 squares\n        if (bit_test(cur, M)) return true;\n        // quick prune: if nothing achievable anymore, break\n        bool any = false; for (int j = 0; j < W; ++j) if (cur[j]) { any = true; break; }\n        if (!any) return false;\n    }\n    // if not found during steps, not nice\n    return false;\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int t; if(!(cin>>t)) return 0; vector<long long> xs(t); long long maxX = 0; for(int i=0;i<t;++i){ cin>>xs[i]; maxX = max(maxX, xs[i]); }\n\n    // Precompute costs of nice staircases with S(n) <= maxX, for n up to a practical bound\n    const int N_LIMIT = 120; // heuristic bound; sufficient for expected inputs\n    vector<long long> costs; costs.reserve(128);\n    for (int n = 1; n <= N_LIMIT; ++n) {\n        long long S = 1LL * n * (n + 1) / 2;\n        if (S > maxX) break; // beyond max query, no need to consider\n        if (isNiceBitset(n, maxX)) {\n            costs.push_back(S);\n        }\n    }\n    sort(costs.begin(), costs.end());\n    // prefix sums to answer queries quickly\n    vector<long long> pref(costs.size() + 1, 0);\n    for (size_t i = 0; i < costs.size(); ++i) pref[i+1] = pref[i] + costs[i];\n\n    for (int i = 0; i < t; ++i) {\n        long long x = xs[i];\n        // max k with pref[k] <= x\n        int k = upper_bound(pref.begin(), pref.end(), x) - pref.begin() - 1;\n        if (k < 0) k = 0;\n        cout << k << \"\\n\";\n    }\n    return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n\n./main << EOF\n4\n1\n8\n6\n1000000000000000000\nEOF"], 
