#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> f;
    Fenwick() : n(0) {}
    Fenwick(int n_) { init(n_); }
    void init(int n_) { n = n_; f.assign(n+1, 0); }
    void add(int i, int delta) { for(; i <= n; i += i & -i) f[i] += delta; }
    int sum(int i) const { int s = 0; for(; i > 0; i -= i & -i) s += f[i]; return s; }
    int range_sum(int l, int r) const { if(l > r) return 0; if(l < 1) l = 1; if(r > n) r = n; return sum(r) - sum(l-1); }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if(!(cin >> n >> q)) return 0;
    string s; cin >> s;
    vector<char> arr(n+1);
    for(int i = 1; i <= n; ++i) arr[i] = s[i-1];

    set<int> Rset, Pset, Sset; // positions for each type
    Fenwick bitR(n), bitP(n), bitS(n);

    for(int i = 1; i <= n; ++i){
        if(arr[i] == 'R'){ Rset.insert(i); bitR.add(i, 1); }
        else if(arr[i] == 'P'){ Pset.insert(i); bitP.add(i, 1); }
        else if(arr[i] == 'S'){ Sset.insert(i); bitS.add(i, 1); }
    }

    auto compute_ans = [&]() -> int {
        int cntR = bitR.sum(n);
        int cntP = bitP.sum(n);
        int cntS = bitS.sum(n);
        // If any type is missing, all players can be champions
        if(cntR == 0 || cntP == 0 || cntS == 0) return n;
        // All three present: use wrap-around intervals
        int minR = *Rset.begin(); int maxP = *Pset.rbegin();
        int minP = *Pset.begin(); int maxS = *Sset.rbegin();
        int minS = *Sset.begin(); int maxR = *Rset.rbegin();

        auto countR = [&](int L, int R){ if(L <= R) return bitR.range_sum(L, R); else return bitR.range_sum(L, n) + bitR.range_sum(1, R); };
        auto countP = [&](int L, int R){ if(L <= R) return bitP.range_sum(L, R); else return bitP.range_sum(L, n) + bitP.range_sum(1, R); };
        auto countS = [&](int L, int R){ if(L <= R) return bitS.range_sum(L, R); else return bitS.range_sum(L, n) + bitS.range_sum(1, R); };

        int badR = countR(minR, maxP);
        int badP = countP(minP, maxS);
        int badS = countS(minS, maxR);
        int maxBad = max({badR, badP, badS});
        return n - maxBad;
    };

    cout << compute_ans() << "\n";

    for(int i = 0; i < q; ++i){
        int p; char c; cin >> p >> c;
        char old = arr[p];
        if(old == 'R') { Rset.erase(p); bitR.add(p, -1); }
        else if(old == 'P') { Pset.erase(p); bitP.add(p, -1); }
        else if(old == 'S') { Sset.erase(p); bitS.add(p, -1); }
        arr[p] = c;
        if(c == 'R') { Rset.insert(p); bitR.add(p, 1); }
        else if(c == 'P') { Pset.insert(p); bitP.add(p, 1); }
        else if(c == 'S') { Sset.insert(p); bitS.add(p, 1); }
        cout << compute_ans() << "\n";
    }
    return 0;
}
